import subprocess, re
repo="/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
edit="/home/runner/work/beetle-in-the-anthill/edit-main"
def sh(cmd): return subprocess.check_output(["git","-C",repo]+cmd).decode()
def msg(sha): return sh(["show","-s","--format=%B",sha])
def body(m):
    lines=m.split("\n"); idx=None
    for i,l in enumerate(lines):
        if l.startswith("Reply-To:"): idx=i; break
    rest=lines[idx+1:]
    while rest and rest[0].strip()=="": rest.pop(0)
    while rest and rest[-1].strip()=="": rest.pop()
    return "\n".join(rest)
def meta(sha):
    m=msg(sha)
    sp=re.search(r'^Speaker: (.*)$',m,re.M).group(1).strip()
    ts=sh(["show","-s","--format=%cI",sha]).strip()
    return sp,ts
